## 标准渲染模板

### 3.1 模板目录结构

```
resources/
├── common/
│   ├── layout/
│   │   └── default.html      # 默认布局模板
│   ├── common.css            # 公共样式
│   └── font/                 # 字体文件
├── help/
│   ├── index.html            # 帮助模板
│   ├── index.css             # 帮助样式
│   └── imgs/                 # 背景图片
└── admin/
    ├── index.html            # 配置界面模板
    └── index.css
```

### 3.2 布局模板详解

#### default.html（标准布局）

```html
<!DOCTYPE html>
<html lang="zh-cn">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width">
  <link rel="preload" href="{{_res_path}}common/font/FZB.woff" as="font">
  <link rel="stylesheet" type="text/css" href="{{_res_path}}common/common.css" />
  <title>{{title}}</title>
  {{block 'css'}}{{/block}}
</head>
<body class="elem-{{element||'hydro'}} {{displayMode||'default'}}-mode" {{@sys.scale}}>
  <div class="container" id="container">
    {{block 'main'}}{{/block}}
    <div class="copyright">{{@sys.copyright}}</div>
  </div>
</body>
</html>
```

#### 继承布局模板

```html
{{extend defaultLayout}}

{{block 'css'}}
<link rel="stylesheet" href="{{_res_path}}/help/index.css" />
<style>
  .container {
    background: url("{{_res_path}}/help/imgs/{{bg}}") center;
  }
</style>
{{/block}}

{{block 'main'}}
<!-- 主内容区域 -->
<div class="content">
  {{each list item}}
  <div class="item">{{item.name}}</div>
  {{/each}}
</div>
{{/block}}
```

### 3.3 帮助界面模板

#### help/index.html

```html
{{extend defaultLayout}}

{{block 'css'}}
<link rel="stylesheet" type="text/css" href="{{_res_path}}/help/index.css" />
<style>
  .container {
    background: url("{{_res_path}}/help/imgs/{{bg}}") center !important;
    background-size: cover !important;
  }
</style>
{{/block}}

{{block 'main'}}
<div class="info-box">
  <div class="head-box type{{bgType}}">
    <div class="title">{{helpCfg.title||"使用帮助"}}</div>
    <div class="label">{{helpCfg.subTitle || "Yunzai-Bot"}}</div>
  </div>
</div>

{{each helpGroup group}}
{{set len = group?.list?.length || 0 }}
<div class="cont-box">
  <div class="help-group">{{group.group}}</div>
  {{if len > 0}}
  <div class="help-table">
    <div class="tr">
      {{each group.list help idx}}
      <div class="td">
        <span class="help-icon" style="{{help.css}}"></span>
        <strong class="help-title">{{help.title}}</strong>
        <span class="help-desc">{{help.desc}}</span>
      </div>
      {{if idx%colCount === colCount-1 && idx>0 && idx< len-1}}
    </div>
    <div class="tr">
      {{/if}}
      {{/each}}
    </div>
  </div>
  {{/if}}
</div>
{{/each}}
{{/block}}
```

#### 帮助配置数据结构

```javascript
// config/system/help_system.js
export const helpCfg = {
  title: "xx帮助",
  subTitle: "Yunzai-Bot & xx-Plugin",
  columnCount: 3,           // 列数
  colWidth: 265,            // 列宽
  theme: "all",
  themeExclude: ["default"],
  style: {
    fontColor: "#ceb78b",
    descColor: "#eee",
    contBgColor: "rgba(6, 21, 31, .5)",
    contBgBlur: 3,
    headerBgColor: "rgba(6, 21, 31, .4)",
    rowBgColor1: "rgba(6, 21, 31, .2)",
    rowBgColor2: "rgba(6, 21, 31, .35)"
  }
}

export const helpList = [
  {
    group: "功能分组名称",
    auth: "master",  // 权限：master/owner/admin（可选）
    list: [
      {
        icon: 1,                    // 图标编号
        title: "#命令",             // 命令
        desc: "功能描述"            // 描述
      }
    ]
  }
]
```

### 3.4 配置界面模板

#### admin/index.html

```html
{{extend defaultLayout}}

{{block 'css'}}
<link rel="stylesheet" href="{{_res_path}}/admin/index.css" />
{{/block}}

{{block 'main'}}
<div class="config-box">
  <div class="config-header">
    <h2>{{title}}</h2>
  </div>

  {{each groups group}}
  <div class="config-group">
    <div class="group-title">{{group.name}}</div>

    {{each group.items item}}
    <div class="config-item">
      <div class="item-label">{{item.label}}</div>
      <div class="item-value">{{item.value}}</div>
      <div class="item-desc">{{item.desc}}</div>
    </div>
    {{/each}}
  </div>
  {{/each}}
</div>
{{/block}}
```

### 3.5 art-template 语法

#### 基础语法

```html
<!-- 变量输出 -->
{{name}}
{{user.name}}
{{user['name']}}

<!-- 不转义输出 HTML -->
{{@htmlContent}}

<!-- 条件判断 -->
{{if user}}
  <div>{{user.name}}</div>
{{else if guest}}
  <div>访客</div>
{{else}}
  <div>匿名</div>
{{/if}}

<!-- 循环 -->
{{each list item index}}
  <div>{{index}}: {{item.name}}</div>
{{/each}}

<!-- 设置变量 -->
{{set temp = value}}

<!-- 引入子模板 -->
{{include './header.html'}}
```

#### 过滤器

```html
<!-- 默认值 -->
{{name | default:'匿名'}}

<!-- 日期格式化 -->
{{time | date:'yyyy-MM-dd'}}

<!-- 截取字符串 -->
{{content | truncate:20}}
```

