## Guoba 配置界面

### 4.1 Guoba 简介

Guoba 是 Yunzai 的图形化配置管理插件，支持通过 Web 界面管理插件配置。

### 4.2 接入 Guoba

#### 创建 guoba.support.js

```javascript
// guoba.support.js
export { supportGuoba } from "./guoba/index.js"
```

#### 创建 guoba/index.js

```javascript
import pluginInfo from "./pluginInfo.js"
import configInfo from "./configInfo.js"

export function supportGuoba() {
  return {
    pluginInfo,
    configInfo
  }
}
```

### 4.3 插件信息配置

#### guoba/pluginInfo.js

```javascript
export default {
  // 插件名称
  name: "yenai-plugin",
  // 插件标题
  title: "椰奶插件",
  // 插件描述
  description: "Yunzai 扩展插件",
  // 作者
  author: "@yenai",
  // 版本
  version: "1.0.0",
  // 仓库地址
  repo: "https://github.com/your-repo/yenai-plugin",
  // 图标
  icon: "mdi:puzzle",
  // 依赖
  depends: []
}
```

### 4.4 配置信息配置

#### guoba/configInfo.js

```javascript
import { schemas, getConfigData, setConfigData } from "./schemas/index.js"

export default {
  schemas,           // 表单 schema
  getConfigData,     // 获取配置方法
  setConfigData      // 保存配置方法
}
```

### 4.5 Schema 定义

#### guoba/schemas/index.js

```javascript
import notice from "./notice.js"
import other from "./other.js"

// 合并所有 schemas
export const schemas = [
  ...notice,
  ...other
]

// 获取配置数据
export function getConfigData() {
  return {
    notice: Config.getNotice(),
    other: Config.other
  }
}

// 保存配置数据
export function setConfigData(data, { Result }) {
  // 保存到配置文件
  Config.setNotice(data.notice)
  Config.setOther(data.other)

  return Result.ok({}, "保存成功")
}
```

#### Schema 字段类型

```javascript
// guoba/schemas/notice.js
export default [
  {
    field: "notice.friendRecall",
    label: "好友撤回通知",
    component: "Switch",        // 组件类型
    required: false,
    defaultValue: true
  },
  {
    field: "notice.groupRecall",
    label: "群撤回通知",
    component: "Switch"
  },
  {
    field: "notice.groupIncrease",
    label: "群成员增加通知",
    component: "Switch"
  },
  {
    field: "notice.groupDecrease",
    label: "群成员减少通知",
    component: "Switch"
  },
  // 分组
  {
    component: "Divider",
    label: "通知设置"
  },
  // 输入框
  {
    field: "notice.customMsg",
    label: "自定义消息",
    component: "Input",
    placeholder: "请输入自定义消息"
  },
  // 数字输入
  {
    field: "notice.timeout",
    label: "超时时间",
    component: "InputNumber",
    min: 0,
    max: 3600,
    defaultValue: 30
  },
  // 下拉选择
  {
    field: "notice.mode",
    label: "通知模式",
    component: "Select",
    options: [
      { label: "简洁", value: "simple" },
      { label: "详细", value: "detail" }
    ]
  },
  // 多选
  {
    field: "notice.types",
    label: "通知类型",
    component: "CheckboxGroup",
    options: [
      { label: "文本", value: "text" },
      { label: "图片", value: "image" }
    ]
  }
]
```

### 4.6 支持的组件类型

| 组件 | 用途 | 配置项 |
|------|------|--------|
| `Switch` | 开关 | `defaultValue` |
| `Input` | 文本输入 | `placeholder` |
| `InputNumber` | 数字输入 | `min`, `max`, `step` |
| `Select` | 下拉选择 | `options` |
| `RadioGroup` | 单选组 | `options` |
| `CheckboxGroup` | 多选组 | `options` |
| `Textarea` | 多行文本 | `rows` |
| `Slider` | 滑块 | `min`, `max`, `step` |
| `Divider` | 分隔线 | `label` |
| `Alert` | 提示信息 | `message`, `type` |

